-- FIX-LB1 LB1-01 (QĐ-111ao, QĐ-112b): an organization installed before the library of policies has none of the eight policies, and no route makes one (R-42), so every
-- decision step that asks a checklist would find no policy in force. This writes, for every organization that exists, each policy of the fixed set that it does not have yet and the first version of
-- each policy that has no published version, with the text and the ground of the issue the installation writes for a new organization (src/modules/policies/initial). Safe to run twice: every statement
-- skips what exists, so a second run writes nothing and a version published by the Super Admin is never touched. An installation made later writes the same through PoliciesBootstrapApi.

-- POL-GEN
INSERT INTO "policies" ("id", "organization_id", "code", "created_at")
SELECT gen_random_uuid(), o."id", 'POL-GEN', now() FROM "organizations" o
 WHERE NOT EXISTS (SELECT 1 FROM "policies" p WHERE p."organization_id" = o."id" AND p."code" = 'POL-GEN');

INSERT INTO "policy_versions" ("id", "organization_id", "policy_id", "version_number", "title", "content", "applicable_roles",
                               "change_note", "requires_reacknowledgement", "published_at", "updated_at")
SELECT gen_random_uuid(), p."organization_id", p."id", 1, 'Quy định chung về sử dụng phần mềm và bảo mật dữ liệu', $pl${"sections":[{"heading":"Mục đích","body":"mọi người dùng phần mềm của công ty đúng mục đích công việc, trên tài khoản công ty, không làm lộ dữ liệu và không phát sinh chi phí ngoài quy trình."},{"heading":"Phạm vi","body":"mọi tài khoản SaaS-Sentry; SaaS trả phí, phần mềm thương mại có bản quyền, phần mềm nội bộ do công ty cấp. Phần mềm miễn phí bên ngoài không phải đối tượng quản lý chi phí (`C-02`) nhưng vẫn chịu quy định 6."},{"heading":"Vai trò","body":"người dùng — tuân thủ, hoàn trả quyền không còn cần; Trưởng phòng — giám sát việc dùng trong phòng; IT Admin — cấp, thu hồi, giữ cấu hình an toàn; Super Admin — ban hành bộ chính sách, ghi sự kiện nhân sự."},{"heading":"Quy định","body":"1. **Mọi quyền qua Request**, không tự cấp theo phòng, chức vụ hay thuộc tính; danh sách phần mềm của phòng chỉ để hướng dẫn (`C-01`, `QĐ-110s`, `QĐ-111c`). — _Đối chiếu:_ Khớp chuẩn · [NIST AC-2](https://csf.tools/reference/nist-sp-800-53/r5/ac/ac-2/)\n2. **Chỉ tài khoản email công ty**; mỗi người một tài khoản và một seat riêng. **Cấm** dùng chung tài khoản, chia sẻ mật khẩu hay chuyển gói cá nhân cho người khác (`C-01`, `QĐ-103d`; điều khoản nhà cung cấp — R12B §1). — _Đối chiếu:_ Khớp chuẩn · [SANS AUP](https://assets.contentstack.io/v3/assets/blt36c2e63521272fdc/blt207beda4b7c14d22/636f1a30e3836b0c88e8f0a8/Acceptable_Use_Policy.pdf); [UT IT0002](https://policy.tennessee.edu/policy/it0002-acceptable-use-of-information-technology-resources/) (S)\n3. Hệ thống **không lưu mật khẩu**; gói cá nhân `K1` đăng ký trên email công ty của chính người dùng. Email/số điện thoại khôi phục và MFA (nếu phần mềm có) chỉ dùng phương thức do công ty kiểm soát, như hộp thư công ty; không gắn số điện thoại, email hay ứng dụng xác thực cá nhân (`QĐ-111q`, `QĐ-111az`). — _Đối chiếu:_ Tương tự thực tế (đã sửa DX-01) · [Google offboarding](https://knowledge.workspace.google.com/admin/users/maintain-data-security-after-an-employee-leaves); [CIS 6](https://cas8.docs.cisecurity.org/en/latest/source/Controls6/)\n4. **Giới hạn gửi Request:** `GH-1` không xin gói đang có quyền hoặc đang có Request mở; `GH-2` tối đa **10** Request cấp mới mỗi tuần lịch, Request đã rút hoặc bị từ chối vẫn tính (`C-19`, `QĐ-111h`). — _Đối chiếu:_ Nội bộ — QĐ\n5. Phần mềm trả phí dùng cho công việc phải có trong danh mục; tài khoản hoặc khoản chi phát sinh ngoài quy trình bị ghi nhận, báo cáo và có thể bị IT thu hồi khi nằm trên tài sản công ty; muốn dùng chính thức thì gửi Request (`C-15`, `QĐ-103y`, `QĐ-104j`). — _Đối chiếu:_ Khớp chuẩn · [SANS AUP](https://assets.contentstack.io/v3/assets/blt36c2e63521272fdc/blt207beda4b7c14d22/636f1a30e3836b0c88e8f0a8/Acceptable_Use_Policy.pdf); [SMU 8.1](https://www.smu.edu/policy/8-information-technology/8-1-acceptable-use) (S)\n6. **Bảo mật dữ liệu:** không đưa dữ liệu cá nhân hoặc thông tin mật của công ty vào phần mềm chưa qua đánh giá của IT (`SBF-15`) hay vào tài khoản cá nhân; phát hiện lộ lọt báo ngay IT Admin (Luật 91/2025/QH15; `FR-3.19` — loại dữ liệu đưa vào). — _Đối chiếu:_ Khớp chuẩn (đã sửa DX-05) · [SANS AUP 4.1.2](https://assets.contentstack.io/v3/assets/blt36c2e63521272fdc/blt207beda4b7c14d22/636f1a30e3836b0c88e8f0a8/Acceptable_Use_Policy.pdf)\n7. **Thông báo theo dõi:** công ty thu dữ liệu sử dụng từ ba nguồn: (a) agent trên máy công ty một người dùng, sau khi nhân viên ký `BM-06` _đã biết rõ_ và xác nhận chủ động thông báo có phiên bản; (b) thời điểm đăng nhập/hoạt động lấy từ trang quản trị của nhà cung cấp; (c) file usage do IT nạp. Dữ liệu chỉ dùng cho cấp, thu hồi và tối ưu chi phí (quy định 8). Máy cá nhân không thu; ứng dụng nhóm _Liên lạc_ không thu usage (`SBF-05`, `SBF-04a`, `SBF-08`, `INV-17`, `ADR-10`, `QĐ-111e`). — _Đối chiếu:_ Khớp chuẩn (đã sửa DX-04) · [Luật 91 Đ25](https://hethongphapluat.com/luat-bao-ve-du-lieu-ca-nhan-2025/dieu-25) (BT); [ICO](https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/employment/monitoring-workers/data-protection-and-monitoring-workers/)\n8. **Dữ liệu usage** chỉ dùng cho cấp, thu hồi và tối ưu chi phí; màn usage không hiện họ tên, ảnh, không xếp hạng người (`QĐ-111aw`, `QĐ-111au`, `OQ-03`). — _Đối chiếu:_ Khớp chuẩn · [ICO](https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/employment/monitoring-workers/data-protection-and-monitoring-workers/); [Luật 91 Đ25](https://hethongphapluat.com/luat-bao-ve-du-lieu-ca-nhan-2025/dieu-25) (BT)\n9. **Thời gian dùng:** quyền có thời hạn được nhắc khi mở cửa sổ tiếp tục 30 ngày và 7 ngày trước ngày hết; không còn cần ⟹ người dùng **hoàn trả** (`BM-03`) (`C-10`, `QĐ-111l`). — _Đối chiếu:_ Tương tự thực tế · [Zluri](https://help.zluri.com/docs/access-request-workflows); [NIST AC-2](https://csf.tools/reference/nist-sp-800-53/r5/ac/ac-2/)\n10. **Điều chuyển:** người chuyển phòng tự xin lại phần mềm còn cần ở phòng mới trong **5 ngày làm việc** ân hạn; ân hạn chỉ giữ quyền dùng phần mềm, còn vai admin nhà cung cấp và IT phụ trách thuê bao ở phòng cũ chuyển ngay trong ngày hiệu lực (`POL-MF3` quy định 2, 8); hết ân hạn quyền cũ bị thu hồi (`QĐ-110p`, `QĐ-110q`). — _Đối chiếu:_ Nội bộ — QĐ (đồng bộ DX-09) · [NIST PS-5](https://csf.tools/reference/nist-sp-800-53/r5/ps/ps-5/)\n11. **Dữ liệu cá nhân:** người dùng tự sửa ảnh đại diện và số điện thoại công việc; yêu cầu xuất/sửa dữ liệu khác được xử lý trong thời hạn Luật 91/2025/QH15 và văn bản hướng dẫn quy định; mục tiêu nội bộ là **10 ngày** nếu luật không quy định ngắn hơn (`QĐ-111at`, `FR-10.5`, `SBF-10`). — _Đối chiếu:_ Nội bộ (đã sửa DX-07) · [Luật 91/2025](https://luatvietnam.vn/bai-viet-lien-quan/luat-91-2025-qh15-405135.html) (S)\n12. **Báo lỗi SaaS** qua phiếu; IT phản hồi đầu tiên trong **1 ngày làm việc** (`QĐ-108f`, `QĐ-111s`). — _Đối chiếu:_ Nội bộ — QĐ\n13. **Dấu vết và xác nhận:** mọi quyết định có người, thời điểm, lý do, Audit Trail; vai áp dụng phải xác nhận đã đọc chính sách hiện hành trước khi vào trang tổng quan (`C-05`, `QĐ-111ar`, `QĐ-111bi`). Super Admin rà soát bộ chính sách ít nhất mỗi năm một lần hoặc khi quyết định nội bộ hay luật liên quan thay đổi; kết quả ghi trong `change_note` của phiên bản mới. — _Đối chiếu:_ Khớp chuẩn (bổ sung DX-16) · [ISO A.5.1](https://hightable.io/iso-27001-annex-a-5-1-policies) (TT); [Vanta](https://help.vanta.com/en/articles/11345499-creating-uploading-and-renewing-a-policy)\n14. Vi phạm chính sách này bị xử lý kỷ luật lao động khi hành vi đó đã được quy định trong nội quy lao động của công ty; công ty bổ sung các hành vi vi phạm chính sách này vào nội quy lao động (Bộ luật Lao động 2019 Điều 118). — _Đối chiếu:_ Khớp chuẩn (đã sửa DX-06) · [SANS AUP 5.3](https://assets.contentstack.io/v3/assets/blt36c2e63521272fdc/blt207beda4b7c14d22/636f1a30e3836b0c88e8f0a8/Acceptable_Use_Policy.pdf); [BLLĐ 2019 Đ118](https://thuvienphapluat.vn/hoi-dap-phap-luat/noi-quy-lao-dong-tu-nam-2021-315238.html) (BT)"},{"heading":"Ngoại lệ","body":"quyền theo vai của Super Admin và Người duyệt chi do IT ghi trực tiếp, có cờ audit (`C-01`, `QĐ-104g`) · seat _tài khoản máy_ là seat thường của một IT Admin có cờ, không phải tài khoản dùng chung của con người (`QĐ-110m`) · nhân viên tự mua bằng tiền của mình cho mình nằm ngoài phạm vi chi phí, nhưng vẫn chịu quy định 6 (`C-15`)."},{"heading":"Căn cứ","body":"Bộ luật Lao động 2019 (Điều 118 — nội quy lao động); Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; nội bộ `C-01`, `C-02`, `C-05`, `C-15`, `C-19`, `FR-8.14`. Nhãn _(đề xuất)_ ở quy định 6 và 14 bỏ theo QĐ ban hành bộ chính sách (DX-05, DX-06), đã ghi sổ `QĐ-112c` (Docs `Bộ chính sách khởi tạo.md` 1.0)."},{"heading":"Tham chiếu","body":"QT A.2, A.3, A.5, A.7; `BM-01`, `BM-03`, `BM-06`; `SBF-05`, `SBF-09`, `SBF-10`."}],"steps":[]}$pl$::jsonb, ARRAY['EMPLOYEE', 'MANAGER', 'IT_ADMIN', 'FINANCE', 'SPENDING_APPROVER']::"AppRole"[],
       'Bộ mẫu SaaS-Sentry 1.0 — công ty xuất bản phiên bản 2 kèm quyết định của mình', true, now(), now()
  FROM "policies" p
 WHERE p."code" = 'POL-GEN'
   AND NOT EXISTS (SELECT 1 FROM "policy_versions" v WHERE v."policy_id" = p."id" AND v."version_number" IS NOT NULL);

-- POL-MF1
INSERT INTO "policies" ("id", "organization_id", "code", "created_at")
SELECT gen_random_uuid(), o."id", 'POL-MF1', now() FROM "organizations" o
 WHERE NOT EXISTS (SELECT 1 FROM "policies" p WHERE p."organization_id" = o."id" AND p."code" = 'POL-MF1');

INSERT INTO "policy_versions" ("id", "organization_id", "policy_id", "version_number", "title", "content", "applicable_roles",
                               "change_note", "requires_reacknowledgement", "published_at", "updated_at")
SELECT gen_random_uuid(), p."organization_id", p."id", 1, 'Chính sách cấp phát quyền dùng phần mềm', $pl${"sections":[{"heading":"Mục đích","body":"nhân viên có đúng công cụ cho công việc hiện tại, trên tài khoản công ty, với chi phí đã được người có thẩm quyền duyệt và ghi khoản cam kết. Ba quyết định, ba vai: nhu cầu — Trưởng phòng; chi — Người duyệt chi; kỹ thuật — IT Admin."},{"heading":"Phạm vi","body":"mọi Request cấp mới (case A/B) và tiếp tục sử dụng, cá nhân hoặc nhóm, từ lúc gửi tới khi tác vụ cấp hoàn tất (`MF-1`)."},{"heading":"Vai trò","body":"Trưởng phòng — quyết nhu cầu, trình lô, xác nhận dùng dự phòng; Người duyệt chi — duyệt chi từng Request hoặc cả lô; IT Admin — đánh giá case B (`POL-SAAS`), chọn nguồn cấp và cấp; Hệ thống — tính tiền, kiểm ngân sách, giới hạn."},{"heading":"Quy định","body":"1. **Một form _Xin phần mềm_, tìm danh mục trước:** case A — gói đã có (kể cả chỉ phòng khác dùng) ⟹ cấp từ kho cho từng người; case B — cả công ty chưa có ⟹ Trưởng phòng duyệt nhu cầu ⟹ IT đánh giá ⟹ ngân sách ⟹ Người duyệt chi; ứng dụng có mà gói chưa có ⟹ case B rút gọn (`QĐ-111a`, `FR-3.4`). — _Đối chiếu:_ Tương tự thực tế · [Loughborough](https://lboro.ac.uk/services/it/topics/saas-guide-5-users-or-more/); [ServiceNow community](https://www.servicenow.com/community/sam-articles/sam-office-hours-q-amp-a-april-2026-emea-apac-session/ta-p/3576818) (S)\n2. **Kiểm trùng ở cửa case B:** tên chuẩn hóa hoặc tên miền trang chủ khớp mục đã có ⟹ từ chối kèm mục đã có, người xin chuyển sang case A (`QĐ-111b`). — _Đối chiếu:_ Tương tự thực tế · [CIS 2.1](https://cas8.docs.cisecurity.org/en/latest/source/Controls2/); [Loughborough](https://lboro.ac.uk/services/it/topics/saas-guide-5-users-or-more/)\n3. **Ai gửi:** mọi tài khoản trừ Super Admin, Người duyệt chi và nhân viên chưa xếp phòng; Request cho một người chỉ do chính người đó gửi; Trưởng phòng gửi nhóm từ 2 người, không gồm mình; Employee gửi nhóm tối đa 10 người cùng phòng, không gồm Trưởng phòng (`QĐ-103b`, `QĐ-100t`, `QĐ-100aa`, `QĐ-103u`). — _Đối chiếu:_ Nội bộ — QĐ\n4. **Giới hạn:** `GH-1`, `GH-2` (10 Request cấp mới/tuần lịch) kiểm khi gửi với từng người thụ hưởng; không còn `GH-3`; Request nhóm vi phạm ở dòng nào thì trả về cả danh sách, không gửi một phần (`C-19`, `QĐ-111h`, `QĐ-106g`). — _Đối chiếu:_ Nội bộ — QĐ\n5. **_Thời gian dùng_ (số tháng):** `K1` bắt buộc 1–9 tháng · `K2`/`K5` 1–12 tháng hoặc _Dùng lâu dài_ · `K4` không hỏi; nhà thầu/thực tập vượt ngày hết hợp đồng ⟹ tự cắt tại ngày đó, mỗi tháng đã bắt đầu tính một tháng (`QĐ-111i`, `FR-2.8`, R-38, R-39). — _Đối chiếu:_ Tương tự thực tế · [Zluri](https://help.zluri.com/docs/access-request-workflows)\n6. **Gói cá nhân `K1` chỉ mua kỳ trả tháng:** chỉ mua gói **tháng** trên email công ty của chính người dùng, không mua gói năm cho cá nhân, tối đa 9 tháng mỗi Request và mỗi lần tiếp tục; nhu cầu dài hạn hoặc nhiều người cùng phần mềm ⟹ ưu tiên gói Team/Business trong kho dùng chung `K2` có trang quản trị (`C-11`, `QĐ-103d`, `QĐ-108a`, `QĐ-111i`; thông lệ R12B §1). — _Đối chiếu:_ Nội bộ — QĐ (đã sửa DX-20)\n7. **Số tiền** = giá tháng × số tháng × số người, giá gốc chưa thuế, bằng VND; phần thuộc năm sau hiện sẵn và **lưu lúc duyệt** (`C-08`, `QĐ-111j`, `QĐ-111k`, `QĐ-111an`). — _Đối chiếu:_ Nội bộ — QĐ\n8. **Định tuyến:** Request trả phí của Trưởng phòng không vào lô, Người duyệt chi quyết một bước; phòng chưa có Trưởng phòng ⟹ Request trả phí và case B đứng chờ; phần mềm nội bộ không phí đã có trong danh mục của Trưởng phòng hoặc phòng chưa có Trưởng phòng ⟹ IT cấp thẳng, cờ audit (`QĐ-103b`, `QĐ-103o`, `QĐ-110i`, `QĐ-111bc`, R-43). — _Đối chiếu:_ Nội bộ — QĐ\n9. **Kiểm tra ngân sách ba kết quả:** trong số cơ sở ⟹ Người duyệt chi · vượt số cơ sở còn trong dự phòng ⟹ Trưởng phòng xác nhận kèm một dòng lý do · vượt dự phòng, chưa có ngân sách hiệu lực hoặc báo giá hết hạn ⟹ **chặn**; không override; kiểm lại lúc duyệt (`C-09`, `FR-3.20`, `QĐ-100u`). — _Đối chiếu:_ Tương tự thực tế · [Oracle Fusion](https://docs.oracle.com/en/cloud/saas/supply-chain-and-manufacturing/25c/fapma/budgetary-control-and-encumberance-accounting.html) (S); [Infor LN](https://docs.infor.com/ln/2024.x/en-us/lnolh/tfbgcug/tdom000022.html) (S)\n10. **Checklist** ở `1.2`, `1.6`, `1.7`: phải trả lời hết, tất cả _Có_ mới duyệt được; lô và Request nhóm dùng một bộ trả lời ghi vào từng Request; quyết định lưu câu trả lời và số phiên bản chính sách (`QĐ-111ap`, `QĐ-111aq`, `QĐ-111be`, `FR-8.13`). — _Đối chiếu:_ Nội bộ — QĐ; phần lưu vết · [ISO A.5.18](https://www.isms.online/iso-27001/annex-a-2022/5-18-access-rights-2022/) (TT)\n11. **Cấp từ kho trước khi mua:** IT Admin phụ trách phòng người nhận gán seat/khóa _Trống_ cùng gói; kho hết ⟹ mua thêm trong phạm vi đã duyệt; `K1` cấp theo checklist `K1` trong thẻ việc (email chính chủ; email/số điện thoại khôi phục và MFA nếu có chỉ dùng phương thức do công ty kiểm soát, không gắn số điện thoại, email hay ứng dụng xác thực cá nhân — `POL-GEN` quy định 3) và bằng chứng (`C-13`, `QĐ-111m`, `QĐ-111az`). — _Đối chiếu:_ Tương tự thực tế (đã sửa DX-01) · [Flexera](https://www.flexera.com/media/pdfs/solution-brief-request-reharvest-servicenow.pdf) (S); [CIS 6](https://cas8.docs.cisecurity.org/en/latest/source/Controls6/)\n12. **Tiếp tục sử dụng:** chỉ cho quyền có thời hạn, cùng gói, cửa sổ 30 ngày trước ngày hết; không tính `GH-2`; duyệt trước hạn ⟹ giữ seat, không mở thu hồi (`QĐ-111l`, `FR-3.22`). — _Đối chiếu:_ Nội bộ — QĐ; cơ chế gần · [Zluri](https://help.zluri.com/docs/access-request-workflows)\n13. **Hạn:** mỗi bước duyệt 2 ngày làm việc, cấp 2 ngày làm việc sau duyệt cuối; quá hạn chỉ nhắc, không tự quyết (`FR-3.8`, `QĐ-100j`, `QĐ-94j`). — _Đối chiếu:_ Nội bộ — QĐ"},{"heading":"Ngoại lệ","body":"quyền theo vai của Super Admin, Người duyệt chi (`QĐ-104g`) · Request xin lại trong ân hạn điều chuyển không bị `GH-1`/`GH-2` chặn (`QĐ-110q`) · seat còn trong ân hạn thu hồi được mua thay khi chờ sẽ vượt SLA, IT ghi lý do (`C-13`) · Request đã duyệt chưa cấp tới 31/12 không hết hiệu lực (`C-10`)."},{"heading":"Căn cứ","body":"Quy chế tài chính nội bộ; nội bộ `QĐ-103b`, `QĐ-103o`, `QĐ-110i`, `QĐ-111a`→`QĐ-111c`, `QĐ-111h`→`QĐ-111m`, `QĐ-111ap`, `QĐ-111aq`, `FR-3.2`→`FR-3.4`, `FR-3.20`→`FR-3.23`, `FR-8.13`."},{"heading":"Tham chiếu","body":"QT `1.1`→`1.11`; `BM-01`, `BM-02`; sơ đồ `MF-1`, `SBF-15`, `SBF-17`, `SBF-19`."}],"steps":[{"code":"1.2","title":"Xác nhận nhu cầu · Trưởng phòng","checklist":[{"code":"1.2-01","text":"Người quyết là trưởng phòng hiệu lực của phòng người yêu cầu và không phải người thụ hưởng","check":"SYSTEM"},{"code":"1.2-02","text":"Không người thụ hưởng nào vướng `GH-1`/`GH-2`; phần mềm case B không trùng mục đã có","check":"SYSTEM"},{"code":"1.2-03","text":"Phòng có Cost Center hiện hành; số tiền và cam kết về Cost Center của chính phòng này","check":"SYSTEM"},{"code":"1.2-04","text":"Nhu cầu gắn với công việc hiện tại của từng người thụ hưởng (đặc quyền tối thiểu)","check":"PERSON"},{"code":"1.2-05","text":"Công cụ người thụ hưởng đang có và danh sách phần mềm của phòng không đáp ứng được nhu cầu này","check":"PERSON"},{"code":"1.2-06","text":"Gói và _Thời gian dùng_ không vượt nhu cầu (`K1` là gói tháng; hệ thống đã giới hạn 1–9 tháng)","check":"PERSON"},{"code":"1.2-07","text":"Đã xem lịch sử quyền của người thụ hưởng với phần mềm này (Request tiếp tục: Request cũ được liên kết)","check":"PERSON"}]},{"code":"1.6","title":"Xác nhận dùng dự phòng · Trưởng phòng","checklist":[{"code":"1.6-01","text":"Số tiền vượt số cơ sở nhưng còn trong dự phòng của phòng","check":"SYSTEM"},{"code":"1.6-02","text":"Người xác nhận không phải người thụ hưởng của Request","check":"SYSTEM"},{"code":"1.6-03","text":"Đã xem phần vượt, phần dự phòng còn lại sau khi dùng và đèn ngân sách của phòng","check":"PERSON"},{"code":"1.6-04","text":"Đã cân nhắc giảm số người, số tháng, số lượng mà vẫn không đáp ứng được nhu cầu","check":"PERSON"},{"code":"1.6-05","text":"Nhu cầu không thể chờ tới khi Finance lập điều chỉnh ngân sách hoặc tới năm sau","check":"PERSON"}]},{"code":"1.7","title":"Duyệt chi · Người duyệt chi","checklist":[{"code":"1.7-01","text":"Người duyệt chi không phải người yêu cầu hay người thụ hưởng","check":"SYSTEM"},{"code":"1.7-02","text":"Số tiền tính từ giá gói hoặc báo giá còn hiệu lực, giá gốc chưa thuế, bằng VND","check":"SYSTEM"},{"code":"1.7-03","text":"Kiểm lại lúc duyệt: trong số cơ sở, hoặc dùng dự phòng đã được Trưởng phòng xác nhận (Request một bước: cờ đã hiện)","check":"SYSTEM"},{"code":"1.7-04","text":"Đã xem nhu cầu đã xác nhận (Request một bước: lý do của người yêu cầu) và lý do dùng dự phòng nếu có","check":"PERSON"},{"code":"1.7-05","text":"Đã xem mức kiểm soát và kết luận đánh giá của IT cho gói; chấp nhận rủi ro còn lại theo kết luận của IT","check":"PERSON"},{"code":"1.7-06","text":"Đã xem số tiền năm nay, số tiền năm sau và cảnh báo mềm (nếu qua năm), tiền trả nhà cung cấp cả năm (nếu lần đầu mua gói năm)","check":"PERSON"},{"code":"1.7-07","text":"Kiểu cấp hợp lý về chi phí: `K1` cho nhu cầu cá nhân ngắn hạn; nhu cầu dài hạn hoặc nhiều người đã cân nhắc kho dùng chung `K2`","check":"PERSON"}]}]}$pl$::jsonb, ARRAY['MANAGER', 'SPENDING_APPROVER', 'IT_ADMIN']::"AppRole"[],
       'Bộ mẫu SaaS-Sentry 1.0 — công ty xuất bản phiên bản 2 kèm quyết định của mình', true, now(), now()
  FROM "policies" p
 WHERE p."code" = 'POL-MF1'
   AND NOT EXISTS (SELECT 1 FROM "policy_versions" v WHERE v."policy_id" = p."id" AND v."version_number" IS NOT NULL);

-- POL-MF2
INSERT INTO "policies" ("id", "organization_id", "code", "created_at")
SELECT gen_random_uuid(), o."id", 'POL-MF2', now() FROM "organizations" o
 WHERE NOT EXISTS (SELECT 1 FROM "policies" p WHERE p."organization_id" = o."id" AND p."code" = 'POL-MF2');

INSERT INTO "policy_versions" ("id", "organization_id", "policy_id", "version_number", "title", "content", "applicable_roles",
                               "change_note", "requires_reacknowledgement", "published_at", "updated_at")
SELECT gen_random_uuid(), p."organization_id", p."id", 1, 'Chính sách thu hồi quyền khi nhân viên nghỉ việc', $pl${"sections":[{"heading":"Mục đích","body":"người đã rời công ty không còn quyền ở bất kỳ ứng dụng nào; seat về kho để cấp lại hoặc giảm ở kỳ sau; hồ sơ được giữ."},{"heading":"Phạm vi","body":"mọi sự kiện nghỉ việc, gồm quyền (`K1`, `K2`, `K4`, `K5`) và trách nhiệm (trưởng phòng, IT Admin phụ trách thuê bao, admin nhà cung cấp) của người nghỉ (`MF-2`)."},{"heading":"Vai trò","body":"Super Admin — xác minh `BM-09`, ghi sự kiện, chỉ định kế nhiệm; Trưởng phòng — gửi `BM-09`, xử lý dữ liệu nghiệp vụ ngoài hệ thống; IT Admin — khóa tài khoản công ty, thu hồi từng quyền, chuyển thuê bao; Hệ thống — chặn đăng nhập, tự hủy Request, tự đóng hồ sơ."},{"heading":"Quy định","body":"1. Sự kiện nghỉ việc chỉ có hiệu lực khi **Super Admin** ghi kèm **căn cứ** ngoài hệ thống (một ô chữ, vd. _QĐ nghỉ việc số 12/2026_); `BM-09` chỉ là thông báo, không bao giờ là căn cứ; không lưu lý do nghỉ (`C-06`, `QĐ-110a`, `QĐ-111bd`). — _Đối chiếu:_ Khớp chuẩn · [NIST AC-2](https://csf.tools/reference/nist-sp-800-53/r5/ac/ac-2/); [ISO A.6.5](https://www.isms.online/iso-27001/annex-a-2022/6-5-responsibilities-after-termination-change-of-employment-2022/) (TT)\n2. **Hai nhịp** theo ô _chặn ngay_: có ngày làm việc cuối ⟹ hệ thống tự chặn khi hết ngày đó; chặn ngay ⟹ ngày cuối = ngày ghi, chặn trong ngày (`QĐ-110b`). — _Đối chiếu:_ Khớp chuẩn · [NIST PS-4](https://csf.tools/reference/nist-sp-800-53/r5/ps/ps-4/); [CIS 6.2](https://controls-assessment-specification.readthedocs.io/en/latest/control-6/control-6.2.html)\n3. Người nghỉ là trưởng phòng ⟹ **bắt buộc** chỉ định kế nhiệm khi ghi; việc đang chờ chuyển sang kế nhiệm ở ngày kế nhiệm có hiệu lực, hạn không đặt lại (`QĐ-110h`). — _Đối chiếu:_ Khớp chuẩn · [ISO A.6.5](https://www.isms.online/iso-27001/annex-a-2022/6-5-responsibilities-after-termination-change-of-employment-2022/) (TT); [NIST PS-4](https://csf.tools/reference/nist-sp-800-53/r5/ps/ps-4/)\n4. Tới mốc chặn, hệ thống **tự hủy** Request còn mở của người nghỉ, giải phóng cam kết chưa chi; không bắt đầu tác vụ cấp mới cho người đó (`QĐ-110d`). — _Đối chiếu:_ Nội bộ — QĐ\n5. **Chặn tài khoản công ty** = đặt lại mật khẩu hộp thư + đăng xuất mọi phiên, đồng thời gỡ email/số điện thoại khôi phục cá nhân (nếu có), thu hồi mật khẩu ứng dụng, khóa bảo mật và quyền OAuth đã cấp, xóa dữ liệu công ty trên thiết bị di động — **trước hoặc đồng thời** với gỡ ở nhà cung cấp; **khóa hẳn hộp thư** chỉ sau khi xong checklist `K1`. Hộp thư được đặt lại mật khẩu thay vì vô hiệu hóa ngay vì checklist `K1` cần hộp thư nhận email _Quên mật khẩu_ (`BM-08` (1a)(1b), `QĐ-110b`, R-1). — _Đối chiếu:_ Tương tự thực tế (đã sửa DX-08) · [Google offboarding](https://knowledge.workspace.google.com/admin/users/maintain-data-security-after-an-employee-leaves); [Microsoft Entra](https://learn.microsoft.com/en-us/entra/identity/users/users-revoke-access)\n6. IT Admin mở tác vụ thu hồi **sau khi chặn**, xong **≤ 1 ngày làm việc** sau mốc chặn; quá hạn nhắc IT Admin phụ trách và Super Admin mỗi ngày làm việc (`QĐ-110c`). — _Đối chiếu:_ Khớp chuẩn · [NIST PS-4](https://csf.tools/reference/nist-sp-800-53/r5/ps/ps-4/); [CIS 6.2](https://controls-assessment-specification.readthedocs.io/en/latest/control-6/control-6.2.html)\n7. **Thu hồi theo kiểu cấp:** `K1` theo checklist — đặt lại mật khẩu hộp thư ⟹ _Quên mật khẩu_ trên phần mềm ⟹ đăng xuất mọi phiên ⟹ tắt gia hạn ⟹ ghi bằng chứng ⟹ khóa hộp thư; `K2` gỡ khỏi workspace, seat về kho _Trống_; `K4` ghi cách xử lý khóa; `K5` bằng chứng (`C-18`, `QĐ-111az`, `QĐ-111p`). — _Đối chiếu:_ Tương tự thực tế · [Microsoft Entra](https://learn.microsoft.com/en-us/entra/identity/users/users-revoke-access)\n8. Hệ thống **không lưu mật khẩu** và không điều khiển Google/M365; IT tick đủ checklist kèm bằng chứng mới hoàn tất được (`QĐ-111q`, `QĐ-111az`). — _Đối chiếu:_ Tương tự thực tế · [CIS 6.2](https://controls-assessment-specification.readthedocs.io/en/latest/control-6/control-6.2.html)\n9. **Trách nhiệm:** IT Admin phụ trách chuyển mọi thuê bao và mục danh mục bằng một thao tác; tới mốc chặn chưa chuyển ⟹ hàng việc IT chung; admin nhà cung cấp còn < 2 ⟹ cờ, còn 0 ⟹ hàng việc IT; việc chưa chuyển không chặn đóng hồ sơ (`QĐ-110j`, `QĐ-110k`, R-26). — _Đối chiếu:_ Khớp chuẩn · [NIST PS-4](https://csf.tools/reference/nist-sp-800-53/r5/ps/ps-4/); [ISO A.6.5](https://www.isms.online/iso-27001/annex-a-2022/6-5-responsibilities-after-termination-change-of-employment-2022/) (TT)\n10. **Không** có bước bàn giao dữ liệu trong hệ thống — dữ liệu nghiệp vụ trong SaaS do Trưởng phòng xử lý ngoài hệ thống trước mốc chặn (`QĐ-110g`). — _Đối chiếu:_ Khớp chuẩn · [NIST PS-4](https://csf.tools/reference/nist-sp-800-53/r5/ps/ps-4/); [Google offboarding](https://knowledge.workspace.google.com/admin/users/maintain-data-security-after-an-employee-leaves)\n11. Hệ thống **tự đóng** hồ sơ khi: nhân viên _đã nghỉ việc_, mọi tác vụ thu hồi hoàn tất, mục (1b) của `BM-08` đã ghi. Hồ sơ quyền, quyết định và Audit Trail được giữ lại vì luật khác yêu cầu lưu chứng từ, đây là ngoại lệ Luật 91/2025/QH15 Điều 25 cho phép; ảnh đại diện và số điện thoại công việc bị xóa (`QĐ-110e`, `QĐ-110f`, `QĐ-111av`, B-1). — _Đối chiếu:_ Khớp chuẩn (đã sửa DX-19) · [PBGDPL Cần Thơ](https://pbgdpl.cantho.gov.vn/quy-dinh-ve-bao-ve-du-lieu-ca-nhan-trong-tuyen-dung-quan-ly-su-dung-nguoi-lao-dong) (BT); [CIS 6.2](https://controls-assessment-specification.readthedocs.io/en/latest/control-6/control-6.2.html)"},{"heading":"Ngoại lệ","body":"hủy nghỉ việc trước _đã nghỉ việc_ cần căn cứ như ghi mới, không tự mở khóa, quyền đã thu hồi phải xin lại; không hủy sau _đã nghỉ việc_ (`QĐ-81`, `QĐ-100q`, R-41) · Super Admin nghỉ ⟹ chuyển giao vai trước (`QĐ-87c`) · người nghỉ là IT Admin ⟹ IT Admin khác làm tác vụ (`SoD-5`) · người đang trong ân hạn điều chuyển nghỉ ⟹ `MF-2` tiếp quản quyền cũ (`QĐ-110r`)."},{"heading":"Căn cứ","body":"Bộ luật Lao động 2019 (căn cứ chấm dứt hợp đồng nằm ngoài hệ thống); Luật 91/2025/QH15; nội bộ `QĐ-110a`→`QĐ-110h`, `QĐ-111az`, `QĐ-111bd`, `FR-2.12`, `FR-2.14`."},{"heading":"Tham chiếu","body":"QT `2.1`→`2.9`; `BM-04`, `BM-08`, `BM-09`; `SBF-13`, `SBF-16`, `SBF-18`."}],"steps":[]}$pl$::jsonb, ARRAY['MANAGER', 'IT_ADMIN']::"AppRole"[],
       'Bộ mẫu SaaS-Sentry 1.0 — công ty xuất bản phiên bản 2 kèm quyết định của mình', true, now(), now()
  FROM "policies" p
 WHERE p."code" = 'POL-MF2'
   AND NOT EXISTS (SELECT 1 FROM "policy_versions" v WHERE v."policy_id" = p."id" AND v."version_number" IS NOT NULL);

-- POL-MF3
INSERT INTO "policies" ("id", "organization_id", "code", "created_at")
SELECT gen_random_uuid(), o."id", 'POL-MF3', now() FROM "organizations" o
 WHERE NOT EXISTS (SELECT 1 FROM "policies" p WHERE p."organization_id" = o."id" AND p."code" = 'POL-MF3');

INSERT INTO "policy_versions" ("id", "organization_id", "policy_id", "version_number", "title", "content", "applicable_roles",
                               "change_note", "requires_reacknowledgement", "published_at", "updated_at")
SELECT gen_random_uuid(), p."organization_id", p."id", 1, 'Chính sách điều chỉnh quyền khi nhân viên chuyển phòng', $pl${"sections":[{"heading":"Mục đích","body":"chuyển phòng không làm tích lũy quyền cũ — thu hồi rồi tự xin lại, không giữ seat; chi phí đi đúng phòng của người giữ."},{"heading":"Phạm vi","body":"mọi điều chuyển phòng có ngày hiệu lực (`MF-3`); không gồm đổi chức vụ hay thôi vai."},{"heading":"Vai trò","body":"Super Admin — ghi điều chuyển, kế nhiệm; Trưởng phòng mới — duyệt nhu cầu Request ở phòng mới; IT Admin phụ trách phòng mới — thu hồi quyền cũ; người chuyển — tự xin lại trong ân hạn."},{"heading":"Quy định","body":"1. Super Admin ghi phòng mới đang hoạt động, ngày hiệu lực ≥ hôm nay và căn cứ (một ô chữ); tối đa một điều chuyển chưa đóng; người chuyển là trưởng phòng cũ ⟹ **bắt buộc** kế nhiệm (`QĐ-110n`, `QĐ-110h`, `QĐ-111bd`). — _Đối chiếu:_ Khớp chuẩn · [NIST PS-5](https://csf.tools/reference/nist-sp-800-53/r5/ps/ps-5/); [NIST AC-2](https://csf.tools/reference/nist-sp-800-53/r5/ac/ac-2/)\n2. **Ân hạn 5 ngày làm việc** (ngày hiệu lực là ngày 1) chỉ giữ quyền dùng phần mềm để công việc không gián đoạn trong lúc người chuyển xin lại quyền ở phòng mới; vai admin nhà cung cấp và IT phụ trách thuê bao ở phòng cũ chuyển ngay trong ngày hiệu lực (quy định 8); hệ thống nhắc người chuyển ngày 1 và 2 ngày làm việc trước khi hết (`QĐ-110p`). — _Đối chiếu:_ Nội bộ (đã sửa DX-09) · [NIST PS-5](https://csf.tools/reference/nist-sp-800-53/r5/ps/ps-5/); [CIS 6.2](https://controls-assessment-specification.readthedocs.io/en/latest/control-6/control-6.2.html)\n3. Người chuyển **tự gửi Request ở phòng mới** qua `MF-1` thường; Request cho phần mềm đang giữ không bị `GH-1` chặn và không tính `GH-1`/`GH-2`; không liên kết quyền cũ (`QĐ-110q`). — _Đối chiếu:_ Khớp chuẩn · [NIST PS-5](https://csf.tools/reference/nist-sp-800-53/r5/ps/ps-5/); [NIST AC-2](https://csf.tools/reference/nist-sp-800-53/r5/ac/ac-2/)\n4. Ngày hiệu lực: hệ thống tự hủy Request trả phí còn mở ở phòng cũ; **cam kết của quyền cũ giải phóng ngay**; phí seat trong ân hạn là thực chi của **phòng mới** theo seat-tháng (`QĐ-110o`, `QĐ-110r`, `QĐ-111bg`). — _Đối chiếu:_ Nội bộ — QĐ\n5. Hết ân hạn ⟹ hệ thống **tự tạo tác vụ thu hồi mọi quyền cũ**, giao IT Admin phụ trách phòng mới, dấu _hệ thống tạo_ (`QĐ-110p`). — _Đối chiếu:_ Khớp chuẩn · [CIS 6.2](https://controls-assessment-specification.readthedocs.io/en/latest/control-6/control-6.2.html); [NIST PS-4](https://csf.tools/reference/nist-sp-800-53/r5/ps/ps-4/)\n6. `K1` của người **vẫn làm việc**: chỉ tắt gia hạn và ghi bằng chứng, người chuyển phối hợp; **không** đặt lại mật khẩu, **không** khóa hộp thư (`QĐ-111az`, R-35). — _Đối chiếu:_ Nội bộ — QĐ\n7. Xin lại **đúng thuê bao** đang giữ: cấp lại kết thúc quyền cũ ngay, không thao tác ở nhà cung cấp, không tạo tác vụ thu hồi quyền đó (R-49). — _Đối chiếu:_ Nội bộ — QĐ\n8. Trách nhiệm ở phòng cũ (IT phụ trách thuê bao, admin nhà cung cấp) chuyển **ngay trong ngày hiệu lực**, không chờ hết ân hạn; IT làm tay theo hàng việc hiện có, cách chuyển như `POL-MF2` quy định 9 (`QĐ-110j`, `QĐ-110k`). — _Đối chiếu:_ Khớp chuẩn (đã sửa DX-09) · [ISO A.6.5](https://www.isms.online/iso-27001/annex-a-2022/6-5-responsibilities-after-termination-change-of-employment-2022/) (TT)\n9. Mọi tác vụ thu hồi quyền cũ xong ⟹ hệ thống lưu ảnh chụp quyền trước/sau và **tự đóng** điều chuyển (`QĐ-110r`). — _Đối chiếu:_ Tương tự thực tế · [NIST AC-2](https://csf.tools/reference/nist-sp-800-53/r5/ac/ac-2/)"},{"heading":"Ngoại lệ","body":"phòng mới chưa có trưởng phòng ⟹ Request đứng chờ, ân hạn không dừng (`QĐ-110i`) · phòng mới chưa có Cost Center ⟹ Request chỉ lưu nháp · nghỉ việc trong ân hạn ⟹ `MF-2` tiếp quản (`QĐ-110r`) · thôi vai không phải điều chuyển, không áp ân hạn (`QĐ-106f`, R-21) · đổi chức vụ chỉ là sửa hồ sơ."},{"heading":"Căn cứ","body":"nội bộ `QĐ-110n`→`QĐ-110r`, `QĐ-111bd`, `QĐ-111bg`, `FR-2.16`."},{"heading":"Tham chiếu","body":"QT `3.1`→`3.8`; `BM-04`, `BM-09`; `SBF-13`, `SBF-16`, `SBF-18`."}],"steps":[]}$pl$::jsonb, ARRAY['MANAGER', 'IT_ADMIN']::"AppRole"[],
       'Bộ mẫu SaaS-Sentry 1.0 — công ty xuất bản phiên bản 2 kèm quyết định của mình', true, now(), now()
  FROM "policies" p
 WHERE p."code" = 'POL-MF3'
   AND NOT EXISTS (SELECT 1 FROM "policy_versions" v WHERE v."policy_id" = p."id" AND v."version_number" IS NOT NULL);

-- POL-MF4
INSERT INTO "policies" ("id", "organization_id", "code", "created_at")
SELECT gen_random_uuid(), o."id", 'POL-MF4', now() FROM "organizations" o
 WHERE NOT EXISTS (SELECT 1 FROM "policies" p WHERE p."organization_id" = o."id" AND p."code" = 'POL-MF4');

INSERT INTO "policy_versions" ("id", "organization_id", "policy_id", "version_number", "title", "content", "applicable_roles",
                               "change_note", "requires_reacknowledgement", "published_at", "updated_at")
SELECT gen_random_uuid(), p."organization_id", p."id", 1, 'Chính sách ngân sách phần mềm năm và rà soát trong năm', $pl${"sections":[{"heading":"Mục đích","body":"mỗi phòng có một ngân sách phần mềm cả năm do Người duyệt chi duyệt, nằm trong Trần năm lãnh đạo giao; trong năm số liệu được chốt hằng tháng, rà soát hằng quý và chỉ thay đổi qua điều chỉnh có duyệt."},{"heading":"Phạm vi","body":"kỳ lập ngân sách (`MF-4` B1→B7) và phần trong năm (`SBF-11`: `4.11`→`4.14`), quy tắc qua năm `X-1`→`X-4`."},{"heading":"Vai trò","body":"Finance — mở kỳ, chốt số, chốt tháng, ký rà soát quý, lập điều chỉnh (không quyết); Trưởng phòng — nộp `BM-10`, giải trình; Người duyệt chi — quyết phiên bản và điều chỉnh, không đặt Trần, không ký rà soát (`SoD-3`, `SoD-8`)."},{"heading":"Quy định","body":"1. Năm tài chính là năm dương lịch; **mọi** năm phải có kỳ lập ngân sách trước khi có phiên bản (`FR-5.1`, `QĐ-104e`, `QĐ-109f`). — _Đối chiếu:_ Tương tự thực tế · [FinOps](https://www.finops.org/framework/capabilities/budgeting/)\n2. **Kỳ:** _Nháp_ ⟹ **Mở kỳ** (báo trưởng phòng kèm file mẫu và số liệu nền) ⟹ hết hạn nộp là **khóa**, không mở lại; Finance nhập Trần năm và Dự phòng kho dùng chung (`QĐ-111z`, `QĐ-111aa`). — _Đối chiếu:_ Tương tự thực tế · [FinOps](https://www.finops.org/framework/capabilities/budgeting/)\n3. `BM-10` = ≥ 1 file theo mẫu + một số tiền đề nghị + ghi chú tùy chọn, nộp trước hạn (`QĐ-111ab`). — _Đối chiếu:_ Nội bộ — QĐ\n4. Finance chốt từng phòng: **số cơ sở** (điền sẵn cam kết sẽ chạy sang năm sau) + **dự phòng** (mặc định 10 %, khác thì có lý do) + ≥ 1 file; thấp hơn cam kết chạy sang ⟹ cờ đỏ, không chặn; phòng không nộp ⟹ chốt từ số liệu nền, có cờ (`QĐ-111ac`, `QĐ-111bb`). — _Đối chiếu:_ Tương tự thực tế; 10 % là nội bộ (DX-21) · [FinOps](https://www.finops.org/framework/capabilities/budgeting/); [Luật NSNN Đ10](https://hethongphapluat.com/luat-ngan-sach-nha-nuoc-2015/dieu-10) (S)\n5. Tổng (số cơ sở + dự phòng) các phòng ≤ **Trần năm − Dự phòng kho dùng chung**, kiểm khi Finance gửi; không chia quý (`QĐ-111aa`, `QĐ-111ac`). — _Đối chiếu:_ Tương tự thực tế · [Sussex virements](https://www.sussex.ac.uk:443/finance/documents/virements-policy---final-approved14dec20.pdf) (S)\n6. Người duyệt chi **bắt buộc** quyết từng phiên bản: chỉ _Duyệt_ hoặc _Trả về sửa_ (lý do bắt buộc); duyệt ⟹ hiện hành, **bất biến cả năm** (`QĐ-111ad`). — _Đối chiếu:_ Tương tự thực tế · [FinOps](https://www.finops.org/framework/capabilities/budgeting/)\n7. **Chốt số hằng tháng** ngày làm việc thứ 5: ảnh chụp không sửa, **không khóa dữ liệu** (hóa đơn muộn vẫn ghi); Finance ký đóng kỳ tháng (`QĐ-111ae`, R-2). — _Đối chiếu:_ Tương tự thực tế · [APQC](https://www.cfo.com/news/metric-of-the-month-cycle-time-for-monthly-close/) (S); [FinOps](https://www.finops.org/framework/capabilities/budgeting/)\n8. **Ngưỡng và đèn** cố định: phần đã dùng chạm 80 %/100 % số cơ sở ⟹ báo trưởng phòng và Finance; _Vàng_/_Đỏ_/_Dưới mức_ theo dự kiến cuối năm; **chặn cứng** khi duyệt Request giữ nguyên, đèn chỉ cảnh báo mềm (`QĐ-111af`, `QĐ-111ai`, R-3). — _Đối chiếu:_ Tương tự thực tế · [FinOps](https://www.finops.org/framework/capabilities/budgeting/); [Cloudaware](https://docs.cloudaware.com/DOCS/finops-budgeting-forecasting-budgets) (S)\n9. **Rà soát quý** (kỳ chốt tháng 3, 6, 9): phòng _Vàng_ (dự kiến cuối năm > số cơ sở hoặc tốc độ chi > 110 % lịch), _Đỏ_ (dự kiến > số cơ sở + dự phòng) hoặc _Dưới mức_ (từ tháng 6, dự kiến < 70 % số cơ sở) giải trình trong 5 ngày làm việc (nguyên nhân, một lần hay kéo dài, hành động, nhu cầu đã biết tới cuối năm); chỉ Finance ký, ký được khi còn phòng chưa giải trình — khi đó Finance ghi danh sách phòng thiếu vào biên bản (`QĐ-111af`, `QĐ-111ah`, R-10, R-17). — _Đối chiếu:_ Tương tự thực tế (đã sửa DX-18) · [FinOps](https://www.finops.org/framework/capabilities/budgeting/)\n10. **Điều chỉnh** — bốn loại _Bổ sung_, _Chuyển_, _Trả lại_, _Giảm Trần năm_: chỉ Finance lập kèm lý do, Người duyệt chi duyệt; chỉ đổi số cơ sở; tổng ≤ Trần năm − Dự phòng kho; Trần không tăng sau khóa kỳ; nguồn không xuống dưới dự kiến cuối năm (`QĐ-111ag`, `QĐ-111bh`, R-36, R-40). — _Đối chiếu:_ Tương tự thực tế · [LSE virement](https://info.lse.ac.uk/staff/divisions/Finance-Division/assets/documents/Financial-Planning-and-Analysis/PDFs/Obsolete-PDFs/Virement-procedure.pdf) (S)\n11. **Qua năm:** số năm sau lưu lúc duyệt Request; 01/01 tự tạo cam kết năm mới; năm sau đã có ngân sách mà vượt ⟹ cảnh báo mềm; chưa có ngân sách ⟹ nhắc Finance và Người duyệt chi từ 01/12 rồi mỗi Thứ Hai (`QĐ-111k`, `QĐ-111ak`→`QĐ-111am`). — _Đối chiếu:_ Nội bộ — QĐ\n12. Phòng mới chỉ tạo trong kỳ, trước lần Finance gửi phiên bản đầu tiên; giữa năm không tạo phòng (`QĐ-111ba`, R-16). — _Đối chiếu:_ Nội bộ — QĐ"},{"heading":"Ngoại lệ","body":"phòng chưa có Cost Center không nộp được `BM-10` · chưa có Người duyệt chi dùng được ⟹ chờ có kiểm soát · lãnh đạo lấy bớt tiền sau khóa kỳ ⟹ _Giảm Trần năm_ trong phần chưa phân bổ, không đủ thì các phòng _Trả lại_ trước (`QĐ-111ag`) · đổi Cost Center giữa năm ⟹ _Chuyển_, miễn luật sàn (`QĐ-111bh`, R-40)."},{"heading":"Căn cứ","body":"Quy chế tài chính nội bộ; Trần ngân sách phần mềm năm do Ban lãnh đạo giao; nội bộ `QĐ-111z`→`QĐ-111am`, `QĐ-111ba`, `QĐ-111bb`, `QĐ-111bh`, `FR-5.1`, `FR-5.15`→`FR-5.18`. Các tham số 10 % dự phòng, ngưỡng 80 %/100 %, đèn 110 %/70 %, chốt tháng ngày làm việc thứ 5 và các hạn 5 ngày làm việc là mặc định nội bộ do dự án chọn, tham khảo thông lệ (ServiceNow, Zylo, FinOps); không phải chuẩn (DX-21)."},{"heading":"Tham chiếu","body":"QT `4.1`→`4.14`; `BM-10`; sơ đồ `MF-4`, `SBF-11`."}],"steps":[{"code":"4.7","title":"Quyết phiên bản ngân sách phòng · Người duyệt chi","checklist":[{"code":"4.7-01","text":"Người quyết khác người lập phiên bản","check":"SYSTEM"},{"code":"4.7-02","text":"Tổng (số cơ sở + dự phòng) các phòng ≤ Trần năm − Dự phòng kho dùng chung","check":"SYSTEM"},{"code":"4.7-03","text":"Đã xem đề nghị `BM-10` của trưởng phòng cạnh phiên bản và file giải thích của Finance","check":"PERSON"},{"code":"4.7-04","text":"Ngân sách phòng không thấp hơn cam kết sẽ chạy sang năm sau, hoặc phần thiếu đã có cách xử lý trong file","check":"PERSON"},{"code":"4.7-05","text":"Dự phòng hợp lý với rủi ro của phòng (mặc định 10 % số cơ sở; khác mặc định có lý do của Finance)","check":"PERSON"},{"code":"4.7-06","text":"Phòng mang cờ _phòng không nộp đề nghị_ (nếu có): số chốt từ số liệu nền là hợp lý","check":"PERSON"}]}]}$pl$::jsonb, ARRAY['FINANCE', 'MANAGER', 'SPENDING_APPROVER']::"AppRole"[],
       'Bộ mẫu SaaS-Sentry 1.0 — công ty xuất bản phiên bản 2 kèm quyết định của mình', true, now(), now()
  FROM "policies" p
 WHERE p."code" = 'POL-MF4'
   AND NOT EXISTS (SELECT 1 FROM "policy_versions" v WHERE v."policy_id" = p."id" AND v."version_number" IS NOT NULL);

-- POL-MF5
INSERT INTO "policies" ("id", "organization_id", "code", "created_at")
SELECT gen_random_uuid(), o."id", 'POL-MF5', now() FROM "organizations" o
 WHERE NOT EXISTS (SELECT 1 FROM "policies" p WHERE p."organization_id" = o."id" AND p."code" = 'POL-MF5');

INSERT INTO "policy_versions" ("id", "organization_id", "policy_id", "version_number", "title", "content", "applicable_roles",
                               "change_note", "requires_reacknowledgement", "published_at", "updated_at")
SELECT gen_random_uuid(), p."organization_id", p."id", 1, 'Chính sách thu hồi seat không sử dụng', $pl${"sections":[{"heading":"Mục đích","body":"seat không dùng — có bằng chứng — được trưởng phòng quyết và thu hồi theo từng người, về kho dùng chung để cấp lại; phòng thôi chịu chi phí seat đó."},{"heading":"Phạm vi","body":"khuyến nghị ghost seat `G3`/`G4` tầng _Cần xem xét_ trở lên (kể cả IT đẩy sớm) và việc thu hồi sau quyết định (`MF-5` `5.4`, `5.5`); `G1` ở `POL-SAAS`, `G2` ở `POL-MF2`."},{"heading":"Vai trò","body":"Trưởng phòng của phòng người giữ seat — quyết _Giữ lại_ / _Thu hồi_ / _Tạm miễn trừ_; IT Admin — thu hồi, được trả lại khuyến nghị một lần; IT, Finance, Người duyệt chi, Super Admin không quyết thay."},{"heading":"Quy định","body":"1. Trưởng phòng quyết từng seat kèm lý do trong **5 ngày làm việc**; quá hạn chỉ nhắc và báo cáo, **không** tự thu hồi (`FR-3.10`, `QĐ-66t`, `C-04`). — _Đối chiếu:_ Tương tự thực tế · [ServiceNow reclaim](https://www.servicenow.com/docs/r/yokohama/it-asset-management/saas-license-management/reclaiming-user-subscriptions-saas.html); [Torii](https://support.toriihq.com/hc/en-us/articles/24406268924955-License-opimization-workflow) (S)\n2. **Checklist `5.4`** trước khi quyết; có _Không_ ⟹ chỉ còn _Thu hồi_; quyết ghost seat không có _Trả về_ (`QĐ-111ap`, `QĐ-111be`, R-24). — _Đối chiếu:_ Nội bộ — QĐ\n3. Seat của **chính trưởng phòng**: tự quyết, lý do bắt buộc, cờ audit _tự quyết_; Finance xem danh sách quyết định _tự quyết_ trong rà soát quý và ghi nhận xét vào biên bản ký (`QĐ-104h`). — _Đối chiếu:_ Nội bộ (đã sửa DX-10) · [GAO](https://dof.ca.gov/media/docs/budget/Standards-for-Internal-Control-in-the-Federal-Government.pdf); [CU Handbook](https://www.cu.edu/controller/procedures/accounting-handbook/internal-controls) (S)\n4. _Tạm miễn trừ_ bắt buộc có thời hạn ≤ **12 tháng**, nhắc trước 7 ngày, hết hạn quay lại đánh giá; _Giữ lại_ ⟹ chu kỳ sau hỏi lại (`FR-3.10`). — _Đối chiếu:_ Tương tự thực tế · [Entra inactive](https://learn.microsoft.com/en-us/entra/identity/monitoring-health/howto-manage-inactive-user-accounts)\n5. Quyền có thời hạn còn ≤ **1 tháng** tới ngày hết — lúc quét hoặc lúc quyết ⟹ khuyến nghị tự đóng, để tự hết hạn (`QĐ-103j`, `QĐ-103y`). — _Đối chiếu:_ Nội bộ — QĐ\n6. IT Admin được **trả lại** khuyến nghị tối đa một lần kèm lý do kỹ thuật (`OI-02`). — _Đối chiếu:_ Nội bộ — QĐ\n7. _Thu hồi_ ⟹ IT gỡ **đúng người đó** sau ân hạn **7 ngày**, theo kiểu cấp; khi trưởng phòng quyết _Thu hồi_, IT Admin báo người giữ seat ngày gỡ dự kiến để họ lưu hoặc chuyển dữ liệu; `K1` của người vẫn làm việc chỉ tắt gia hạn và ghi bằng chứng; không hủy Request nhóm hay thuê bao (`QĐ-94j`, `C-18`, R-35). — _Đối chiếu:_ Tương tự thực tế (đã sửa DX-11) · [ServiceNow rule](https://www.servicenow.com/docs/bundle/zurich-it-asset-management/page/product/software-asset-management2/task/add-reclamation-rule-sub.html); [Multiplier](https://multiplierhq.com/blog/automated-license-reclamation-policies-notifications-and-downgrade-flows) (S)\n8. Thu hồi **không** đồng nghĩa giảm phí; tiết kiệm thực chỉ ghi khi hóa đơn kỳ sau thấp hơn (`C-14`). — _Đối chiếu:_ Tương tự thực tế · [Zylo workflows](https://zylo.com/blog/zylo-tips-using-workflows-to-reclaim-unused-saas-licenses)"},{"heading":"Ngoại lệ","body":"seat tài khoản máy và người đang ân hạn điều chuyển không vào khuyến nghị (`QĐ-110m`, `QĐ-110p`) · phòng chưa có trưởng phòng ⟹ quyết định chờ có kiểm soát, Super Admin được cảnh báo (`C-07`) · thu hồi vì bảo mật (`MF-2`, `MF-3`) không áp luật 1 tháng."},{"heading":"Căn cứ","body":"nội bộ `FR-3.10`, `FR-4.12`, `QĐ-103j`, `QĐ-103y`, `QĐ-104h`, `QĐ-111be`, `C-04`, `C-14`. Các tham số 5 ngày làm việc, ân hạn 7 ngày, miễn trừ tối đa 12 tháng, nhắc trước 7 ngày và mốc còn 1 tháng là mặc định nội bộ do dự án chọn, tham khảo thông lệ (ServiceNow, Zylo, FinOps); không phải chuẩn (DX-21)."},{"heading":"Tham chiếu","body":"QT `5.4`, `5.5`; sơ đồ `MF-5`, `SBF-18`."}],"steps":[{"code":"5.4","title":"Quyết ghost seat · Trưởng phòng","checklist":[{"code":"5.4-01","text":"Người quyết là trưởng phòng hiệu lực của phòng người giữ seat","check":"SYSTEM"},{"code":"5.4-02","text":"Khuyến nghị có gói bằng chứng đã chụp (nguồn, mốc thời gian, độ phủ, ngưỡng)","check":"SYSTEM"},{"code":"5.4-03","text":"Người giữ seat vẫn cần phần mềm này cho công việc hiện tại","check":"PERSON"},{"code":"5.4-04","text":"Có lý do cụ thể cho việc ít hoặc không dùng (nghỉ phép, dự án theo mùa, việc theo kỳ) và sẽ dùng lại","check":"PERSON"},{"code":"5.4-05","text":"Thu hồi rồi xin lại khi cần qua `MF-1` sẽ gây gián đoạn công việc đáng kể","check":"PERSON"},{"code":"5.4-06","text":"Chi phí giữ seat tới chu kỳ rà soát sau là hợp lý so với lợi ích","check":"PERSON"}]}]}$pl$::jsonb, ARRAY['MANAGER', 'IT_ADMIN']::"AppRole"[],
       'Bộ mẫu SaaS-Sentry 1.0 — công ty xuất bản phiên bản 2 kèm quyết định của mình', true, now(), now()
  FROM "policies" p
 WHERE p."code" = 'POL-MF5'
   AND NOT EXISTS (SELECT 1 FROM "policy_versions" v WHERE v."policy_id" = p."id" AND v."version_number" IS NOT NULL);

-- POL-USAGE
INSERT INTO "policies" ("id", "organization_id", "code", "created_at")
SELECT gen_random_uuid(), o."id", 'POL-USAGE', now() FROM "organizations" o
 WHERE NOT EXISTS (SELECT 1 FROM "policies" p WHERE p."organization_id" = o."id" AND p."code" = 'POL-USAGE');

INSERT INTO "policy_versions" ("id", "organization_id", "policy_id", "version_number", "title", "content", "applicable_roles",
                               "change_note", "requires_reacknowledgement", "published_at", "updated_at")
SELECT gen_random_uuid(), p."organization_id", p."id", 1, 'Chính sách rà soát mức sử dụng và tối ưu chi phí', $pl${"sections":[{"heading":"Mục đích","body":"dữ liệu sử dụng được thu, khớp và đọc đúng mục đích, đủ tin cậy để đề xuất thu hồi và giảm seat, không biến thành công cụ giám sát cá nhân."},{"heading":"Phạm vi","body":"nạp usage, khớp danh tính, phát hiện seat lãng phí, IT đẩy sớm khuyến nghị (`MF-5` `5.1`→`5.3`, `SBF-04`, `SBF-04a`), chỉ số tối ưu chi phí (`C-14`)."},{"heading":"Vai trò","body":"IT Admin — nạp và khớp usage, rà tầng _Theo dõi_, đẩy sớm; Trưởng phòng — nhận khuyến nghị từ tầng _Cần xem xét_, dùng mức dùng khi giải trình quý; Hệ thống — quét, lọc, phân tầng, lưu bằng chứng."},{"heading":"Quy định","body":"1. **Nhịp quét:** `G1`/`G2` hằng ngày, `G3`/`G4` hằng tuần; _usage thấp_ chỉ là _không hoạt động_ (`G3`/`G4`), không có `G5` (`FR-4.12b`, `QĐ-111ay`). — _Đối chiếu:_ Tương tự thực tế · [ServiceNow M365](https://www.servicenow.com/docs/r/yokohama/it-asset-management/software-asset-management/o365-usage-activity.html) (S); [CloudEagle](https://cloudeagle.ai/optimize/license-harvesting) (S)\n2. **Nguồn:** file usage IT nạp qua xem trước, kết quả máy công ty đã ký `BM-06`, danh sách tài khoản từ trang quản trị nhà cung cấp; ứng dụng nhóm _Liên lạc_ không thu usage (`SBF-04a`, `SBF-05`, `SBF-08`, `ADR-10`). — _Đối chiếu:_ Tương tự thực tế · [ServiceNow rule](https://www.servicenow.com/docs/bundle/zurich-it-asset-management/page/product/software-asset-management2/task/add-reclamation-rule-sub.html); [Zylo workflows](https://zylo.com/blog/zylo-tips-using-workflows-to-reclaim-unused-saas-licenses)\n3. **Quyền đọc:** IT Admin chỉ đọc usage của phòng mình phụ trách; phòng chưa có IT phụ trách ⟹ mọi IT Admin đọc được; ghi (nạp, khớp) thì IT khác làm thay được (`QĐ-111ax`, R-20). — _Đối chiếu:_ Tương tự thực tế · [ICO](https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/employment/monitoring-workers/data-protection-and-monitoring-workers/)\n4. **Riêng tư:** màn tổng hợp đo số ngày hoạt động + số ngày có dữ liệu; theo người chỉ trạng thái + mã nhân viên, không họ tên, ảnh, không xếp hạng; usage chỉ dùng cho cấp, thu hồi, tối ưu chi phí (`QĐ-111aw`, `QĐ-111au`, `OQ-03`). — _Đối chiếu:_ Khớp chuẩn · [Luật 91 Đ25](https://hethongphapluat.com/luat-bao-ve-du-lieu-ca-nhan-2025/dieu-25) (BT); [ICO](https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/employment/monitoring-workers/data-protection-and-monitoring-workers/)\n5. **Khớp danh tính:** một định danh một nhân viên; bản ghi chưa khớp được khớp tay trong kết quả import và không dùng để kết luận (`QĐ-111ax`, `TC-4`). — _Đối chiếu:_ Tương tự thực tế · [Entra inactive](https://learn.microsoft.com/en-us/entra/identity/monitoring-health/howto-manage-inactive-user-accounts)\n6. **Tầng không hoạt động:** _Theo dõi_ 30–59 ngày · _Cần xem xét_ ≥ 60 · _Cần xử lý_ ≥ 90 hoặc chưa từng hoạt động; seat mới có 14 ngày ân hạn; qua đủ 8 cổng lọc mới sinh khuyến nghị (`FR-4.9`, `FR-4.12`, `FR-4.13`). — _Đối chiếu:_ Tương tự thực tế (đã xử lý DX-17, DX-21) · [ServiceNow rule](https://www.servicenow.com/docs/bundle/zurich-it-asset-management/page/product/software-asset-management2/task/add-reclamation-rule-sub.html); [Productiv](https://help.productiv.com/hc/en-us/articles/4406713891213) (S)\n7. **Đẩy sớm:** IT chỉ đẩy `G3`/`G4` từ _Theo dõi_ sang _Cần xem xét_, theo checklist `5.3`; không đẩy seat tài khoản máy hay người đang ân hạn điều chuyển (`QĐ-111ay`, `QĐ-111be`). — _Đối chiếu:_ Tương tự thực tế · [Zylo workflows](https://zylo.com/blog/zylo-tips-using-workflows-to-reclaim-unused-saas-licenses)\n8. **Không tự động hóa:** ít/không dùng chỉ là căn cứ xem xét; hệ thống không tự thu hồi hay tự chặn ứng dụng (`C-04`, `SoD-6`). — _Đối chiếu:_ Nội bộ — QĐ; lựa chọn có chủ đích, khác · [ServiceNow reclaim](https://www.servicenow.com/docs/r/yokohama/it-asset-management/saas-license-management/reclaiming-user-subscriptions-saas.html)\n9. **Tối ưu chi phí:** tỷ lệ chi phí seat _Trống_ vượt **10 %** chi phí kho ⟹ cảnh báo IT cấp lại hoặc giảm ở điểm điều chỉnh; báo cáo ba con số tách rời — tiềm năng, _tránh được_, thực — chỉ _thực_ là giảm chi (`C-14`, `C-12`). — _Đối chiếu:_ Nội bộ — QĐ (DX-21); tham khảo · [Zylo license waste](https://zylo.com/solutions/license-waste) (S)\n10. Rà soát quý hiện mức dùng và cam kết dài hạn; ít dùng xử lý qua `MF-5`, không rút thời hạn Request (`QĐ-111aj`). — _Đối chiếu:_ Tương tự thực tế · [FinOps](https://www.finops.org/framework/capabilities/budgeting/)"},{"heading":"Ngoại lệ","body":"nguồn quá cũ hoặc thiếu cửa sổ dữ liệu ⟹ không chạy rule (`QĐ-101b`) · máy cá nhân, máy dùng chung là điểm mù, không thu (`SBF-05`) · tài khoản email cá nhân chỉ phát hiện được qua usage (`QĐ-111y`, R-18)."},{"heading":"Căn cứ","body":"Luật 91/2025/QH15 (biện pháp công nghệ quản lý người lao động trên cơ sở người lao động biết rõ); nội bộ `QĐ-111aw`→`QĐ-111ay`, `QĐ-111be`, `OQ-03`, `ADR-10`, `FR-4.9`, `FR-4.12`, `FR-4.13`, `FR-5.10`. Các tham số 14 ngày ân hạn seat mới, 8 cổng lọc, 10 % seat trống và mốc 30/60/90 ngày là mặc định nội bộ do dự án chọn, tham khảo thông lệ (ServiceNow, Zylo, FinOps); không phải chuẩn (DX-21; 14 ngày giữ theo DX-17)."},{"heading":"Tham chiếu","body":"QT `5.1`→`5.3`, A.4; `SBF-05`, `SBF-08`."}],"steps":[{"code":"5.3","title":"Đẩy sớm khuyến nghị `G3`/`G4` · IT Admin","checklist":[{"code":"5.3-01","text":"Khuyến nghị `G3`/`G4` ở tầng _Theo dõi_, đã qua đủ 8 cổng lọc (nguồn còn mới, danh tính đã khớp, không phải seat tài khoản máy, không ân hạn)","check":"SYSTEM"},{"code":"5.3-02","text":"Quyền có thời hạn còn trên 1 tháng tới ngày hết _Thời gian dùng_","check":"SYSTEM"},{"code":"5.3-03","text":"Đã đối chiếu thêm một nguồn (trang quản trị nhà cung cấp hoặc nguồn usage khác): không hoạt động là thật, không do lỗi thu thập","check":"PERSON"},{"code":"5.3-04","text":"Có lý do không chờ tới ngưỡng 60 ngày: điểm điều chỉnh hoặc kỳ gia hạn sắp tới, có Request chờ seat cùng gói, hoặc chi phí seat đáng kể","check":"PERSON"},{"code":"5.3-05","text":"Không biết lý do chính đáng nào cho việc tạm không dùng (nghỉ phép ngắn chưa ghi, dự án theo mùa)","check":"PERSON"},{"code":"5.3-06","text":"Đã ghi chú căn cứ đẩy sớm để trưởng phòng đọc khi quyết","check":"PERSON"}]}]}$pl$::jsonb, ARRAY['IT_ADMIN', 'MANAGER']::"AppRole"[],
       'Bộ mẫu SaaS-Sentry 1.0 — công ty xuất bản phiên bản 2 kèm quyết định của mình', true, now(), now()
  FROM "policies" p
 WHERE p."code" = 'POL-USAGE'
   AND NOT EXISTS (SELECT 1 FROM "policy_versions" v WHERE v."policy_id" = p."id" AND v."version_number" IS NOT NULL);

-- POL-SAAS
INSERT INTO "policies" ("id", "organization_id", "code", "created_at")
SELECT gen_random_uuid(), o."id", 'POL-SAAS', now() FROM "organizations" o
 WHERE NOT EXISTS (SELECT 1 FROM "policies" p WHERE p."organization_id" = o."id" AND p."code" = 'POL-SAAS');

INSERT INTO "policy_versions" ("id", "organization_id", "policy_id", "version_number", "title", "content", "applicable_roles",
                               "change_note", "requires_reacknowledgement", "published_at", "updated_at")
SELECT gen_random_uuid(), p."organization_id", p."id", 1, 'Chính sách danh mục, mua sắm, chứng từ và kho phần mềm dùng chung', $pl${"sections":[{"heading":"Mục đích","body":"chỉ phần mềm đã đánh giá mới vào danh mục; mỗi gói dùng chung có một chủ trách nhiệm, đủ người quản trị; mọi khoản mua có chứng từ hợp lệ và được Finance ký trước khi xuất tiền."},{"heading":"Phạm vi","body":"đánh giá và đưa phần mềm mới vào danh mục (`SBF-15`), mua, hóa đơn, nguồn tiền (`SBF-19`), kho `K2`/`K4`, thuê bao, admin nhà cung cấp, điểm điều chỉnh (`SBF-20`)."},{"heading":"Vai trò","body":"IT Admin — đánh giá case B, tạo mục, phụ trách thuê bao, mua và nộp hóa đơn; Finance — đối chiếu, ký xác nhận xuất tiền hoặc trả lại; Super Admin — phân công IT Admin phụ trách phòng."},{"heading":"Quy định","body":"1. **Đánh giá case B** do IT Admin làm **sau** khi trưởng phòng duyệt nhu cầu: điều khoản, giá, kiểu cấp, mức kiểm soát, loại dữ liệu; kết luận nội bộ / trả phí / không đủ điều kiện (kèm phương án thay thế); case B rút gọn chỉ đánh giá gói (`QĐ-111a`, `FR-3.19`). — _Đối chiếu:_ Khớp chuẩn · [CSF GV.SC](https://csf.tools/reference/nist-cybersecurity-framework/v2-0/gv/gv-sc/); [CU](https://cu.edu/security/security-guidance-software-service)\n2. **Khai mục mới** = một thao tác tạo ứng dụng + gói; ô _Loại_ = nhóm chức năng bắt buộc (7 nhóm, _Liên lạc_ và _Khác_ cố định); kiểu cấp quyết mô hình giá; giá nhập VND (`QĐ-111d`, `QĐ-111f`, `QĐ-111bf`, `QĐ-111an`, B-5). — _Đối chiếu:_ Nội bộ — QĐ\n3. **Chống trùng:** IT tạo ứng dụng/gói trùng ⟹ bị từ chối kèm mục đã có, Request gắn vào mục đó (`QĐ-111b`, R-25). — _Đối chiếu:_ Tương tự thực tế · [CIS 2.1](https://cas8.docs.cisecurity.org/en/latest/source/Controls2/); [Loughborough](https://lboro.ac.uk/services/it/topics/saas-guide-5-users-or-more/)\n4. **Người phụ trách:** người tạo mục là IT Admin phụ trách, đổi bằng _chuyển phụ trách_; không có Business Owner; mỗi IT Admin phụ trách **tối đa 4 phòng** (`QĐ-111g`, `QĐ-110l`). — _Đối chiếu:_ Khớp chuẩn · [CIS 15.1](https://cas8.docs.cisecurity.org/en/latest/source/Controls15/)\n5. **Kho dùng chung:** mỗi (ứng dụng, gói) `K2`/`K4` là một thuê bao có một IT Admin phụ trách; thuê bao trùng bị chặn khi vận hành; hợp đồng chỉ liên kết thuê bao kho (`C-03`, `QĐ-104k`, `QĐ-111t`). — _Đối chiếu:_ Tương tự thực tế · [Ramp](https://ramp.com/blog/brex-vs-expensify-vs-ramp)\n6. **Hồ sơ thuê bao:** tài khoản công ty sở hữu thuê bao là **email công ty** (vd. `it-saas@cty.vn`), không lưu mật khẩu; danh sách admin nhà cung cấp **≥ 2 IT Admin đang làm việc** với `K2` và `K4` có trang quản trị; < 2 ⟹ cờ, 0 ⟹ hàng việc IT (`QĐ-110k`, `QĐ-110u`, `QĐ-111r`, R-53). — _Đối chiếu:_ Tương tự thực tế · [Google offboarding](https://knowledge.workspace.google.com/admin/users/maintain-data-security-after-an-employee-leaves); [NIST PS-4](https://csf.tools/reference/nist-sp-800-53/r5/ps/ps-4/)\n7. **Cấp từ kho trước khi mua;** số seat thuê bao `K2`/`K4` tăng ⟹ báo IT Admin phụ trách thuê bao, không thêm bước duyệt (`C-13`, `QĐ-110v`, S-4). — _Đối chiếu:_ Tương tự thực tế · [Flexera](https://www.flexera.com/media/pdfs/solution-brief-request-reharvest-servicenow.pdf) (S); [Ramp](https://ramp.com/blog/brex-vs-expensify-vs-ramp)\n8. **Điểm điều chỉnh** (gói tháng 7 ngày trước ngày thanh toán, gói năm 30 ngày trước hạn báo hủy): gia hạn **đúng số seat hệ thống tính**, không seat đệm, chỉ vượt khi nhà cung cấp buộc tối thiểu kèm bằng chứng; không có quyết định _không gia hạn_ khi còn quyền đang gán (`C-12`, `QĐ-104d`). — _Đối chiếu:_ Tương tự thực tế · [Zylo workflows](https://zylo.com/blog/zylo-tips-using-workflows-to-reclaim-unused-saas-licenses)\n9. **Mua và nộp hóa đơn:** IT thực hiện mọi lần mua, nộp **mỗi hóa đơn một đề nghị** kèm yêu cầu tiền trong **5 ngày làm việc**, tick nguồn tiền **Thẻ công ty** hoặc **IT ứng tiền trước**, ghi số VND thực bị trừ, tách tiền hàng và thuế (`QĐ-111u`, `QĐ-111an`, `QĐ-103w`). — _Đối chiếu:_ Nội bộ — QĐ (tách tiền hàng–thuế theo NĐ 70/2025)\n10. **Chứng từ hợp lệ.** Nhà cung cấp trong nước: hóa đơn ghi tên, địa chỉ, mã số thuế của công ty (NĐ 123/2020/NĐ-CP, sửa đổi bởi NĐ 70/2025/NĐ-CP). Nhà cung cấp nước ngoài không phát hành hóa đơn GTGT Việt Nam: lưu hóa đơn/biên nhận của nhà cung cấp, ghi tên công ty khi trang cho phép, theo hướng dẫn của kế toán. Khoản mua từ **5 triệu đồng** trở lên thanh toán không dùng tiền mặt và lưu chứng từ thẻ/chuyển khoản (Luật Thuế GTGT 48/2024/QH15 Điều 14 khoản 2 điểm b; NĐ 181/2025/NĐ-CP Điều 26; NĐ 320/2025/NĐ-CP Điều 9 khoản 1 điểm c). Không chia một lần mua thành nhiều hóa đơn để tránh ngưỡng. Finance kiểm bằng mắt lúc ký (quy định 12), hệ thống không ép (R12B §1, §3). — _Đối chiếu:_ Khớp chuẩn (đã sửa DX-02) · [MOF Hỏi đáp](https://portal.mof.gov.vn/hoidapcstc/home/cthoidap/157371) (BT); [LuatVietnam NĐ 320](https://luatvietnam.vn/tin-van-ban-moi/hoa-don-tu-5-trieu-dong-phai-thanh-toan-khong-tien-mat-de-duoc-tru-thue-tndn-186-106006-article.html) (BT)\n11. **IT ứng tiền trước** chỉ trong phạm vi Request đã duyệt; Request đã duyệt là văn bản giao việc cho IT mua thay công ty. IT thanh toán bằng thẻ hoặc chuyển khoản, không dùng tiền mặt. Công ty hoàn lại bằng chuyển khoản ngoài hệ thống; không có bước IT xác nhận nhận tiền hay danh sách nợ IT. Khoản lặp hằng tháng ưu tiên Thẻ công ty _(đề xuất)_ (`QĐ-111v`; R12B §3). — _Đối chiếu:_ Khớp chuẩn (đã sửa DX-03) · [LuatVietnam NĐ 320](https://luatvietnam.vn/tin-van-ban-moi/hoa-don-tu-5-trieu-dong-phai-thanh-toan-khong-tien-mat-de-duoc-tru-thue-tndn-186-106006-article.html) (BT); [CV 730/TNI-QLDN3](https://thuvienphapluat.vn/cong-van/Thue-Phi-Le-Phi/Cong-van-730-TNI-QLDN3-2026-giai-dap-thu-tuc-thue-Tay-Ninh-696234.aspx) (S)\n12. **Finance** đối chiếu trong 5 ngày làm việc ⟹ **ký xác nhận xuất tiền** (cả hai nguồn tiền) hoặc trả lại kèm lý do; người nộp và người ký là hai người khác nhau; thực chi vào tháng của kỳ dịch vụ (`QĐ-111u`, `QĐ-111w`, `SoD-3`). — _Đối chiếu:_ Khớp chuẩn · [NIST AC-5](https://csf.tools/reference/nist-sp-800-53/r5/ac/ac-5/); [GAO](https://dof.ca.gov/media/docs/budget/Standards-for-Internal-Control-in-the-Federal-Government.pdf)\n13. Hóa đơn trùng (nhà cung cấp + số hóa đơn) bị chặn lúc nộp; lệch số lượng/đơn giá theo tiền gốc ⟹ xác nhận theo số đã nhận và mở `SBF-11a` song song; gói tháng quá 5 ngày làm việc sau ngày thanh toán chưa có hóa đơn ⟹ cờ (`QĐ-111x`, R-30, R-44). — _Đối chiếu:_ Nội bộ — QĐ\n14. **Không** nhập sao kê; bằng chứng ngoài là hóa đơn nhà cung cấp và danh sách tài khoản xuất từ trang quản trị (`QĐ-111y`). — _Đối chiếu:_ Nội bộ — QĐ"},{"heading":"Ngoại lệ","body":"thuê bao trùng chỉ được ghi ở bước khởi tạo, kèm cảnh báo _nên gộp_ (`SBF-01`) · thuê bao cũ thiếu email sở hữu hoặc admin ⟹ gắn cờ, không chặn (`QĐ-110` G3) · Finance xác nhận hóa đơn có người thụ hưởng là chính mình ⟹ cờ audit (`QĐ-104h`) · `K1` không thuộc kho: gói tháng gắn email từng người."},{"heading":"Căn cứ","body":"Luật Thuế GTGT số 48/2024/QH15; Nghị định 181/2025/NĐ-CP (khấu trừ GTGT); Nghị định 320/2025/NĐ-CP (chi phí được trừ TNDN); Nghị định 123/2020/NĐ-CP sửa đổi bởi Nghị định 70/2025/NĐ-CP (hóa đơn, chứng từ). Nhãn _(đề xuất)_ ở quy định 10 và 11 (trừ vế khoản lặp ưu tiên Thẻ công ty) bỏ theo QĐ ban hành bộ chính sách (DX-02, DX-03), đã ghi sổ `QĐ-112c` (Docs `Bộ chính sách khởi tạo.md` 1.0). Nội bộ `QĐ-103l`, `QĐ-103w`, `QĐ-104d`, `QĐ-104k`, `QĐ-110k`, `QĐ-110l`, `QĐ-110u`, `QĐ-110v`, `QĐ-111b`→`QĐ-111g`, `QĐ-111r`, `QĐ-111t`→`QĐ-111y`, `FR-1.1`, `FR-1.9`, `FR-3.19`, `FR-5.3`, `FR-5.4`."},{"heading":"Tham chiếu","body":"QT `1.3`, C.1, C.2; `BM-02`, `BM-05`."}],"steps":[{"code":"1.3","title":"Đánh giá phần mềm mới (case B) · IT Admin","checklist":[{"code":"1.3-01","text":"Trưởng phòng đã duyệt nhu cầu trước bước đánh giá","check":"SYSTEM"},{"code":"1.3-02","text":"Không trùng mục đã có (tên chuẩn hóa, tên miền trang chủ); trùng thì Request đã gắn vào mục đã có","check":"SYSTEM"},{"code":"1.3-03","text":"Không có phần mềm trong danh mục đáp ứng cùng nhu cầu với chi phí thấp hơn","check":"PERSON"},{"code":"1.3-04","text":"Điều khoản nhà cung cấp cho phép dùng cho doanh nghiệp và cách cấp dự kiến (mỗi người một tài khoản, không dùng chung đăng nhập); khi ngừng dùng, công ty xuất được dữ liệu của mình và yêu cầu nhà cung cấp xóa được dữ liệu","check":"PERSON"},{"code":"1.3-05","text":"Đã xác định loại dữ liệu đưa vào; dữ liệu cá nhân hoặc thông tin mật chỉ khi nhà cung cấp có bằng chứng bảo mật (chứng nhận SOC 2/ISO 27001 hoặc điều khoản xử lý dữ liệu)","check":"PERSON"},{"code":"1.3-06","text":"Kiểm soát được: có trang quản trị hoặc xuất được danh sách thành viên/usage; tài khoản quản trị dùng SSO hoặc MFA nếu nhà cung cấp hỗ trợ","check":"PERSON"},{"code":"1.3-07","text":"Kiểu cấp đúng bản chất (`K1` gói tháng cá nhân; `K2`/`K4` kho dùng chung; `K4` chỉ khóa vĩnh viễn, đã tick _có trang quản trị_ nếu có)","check":"PERSON"},{"code":"1.3-08","text":"Giá gói hoặc báo giá còn hiệu lực, bằng VND (`K2`: giá tháng quy đổi), đã đối chiếu với nguồn của nhà cung cấp","check":"PERSON"}]}]}$pl$::jsonb, ARRAY['IT_ADMIN', 'FINANCE']::"AppRole"[],
       'Bộ mẫu SaaS-Sentry 1.0 — công ty xuất bản phiên bản 2 kèm quyết định của mình', true, now(), now()
  FROM "policies" p
 WHERE p."code" = 'POL-SAAS'
   AND NOT EXISTS (SELECT 1 FROM "policy_versions" v WHERE v."policy_id" = p."id" AND v."version_number" IS NOT NULL);
